package com.trombokendu.chronos.persistence;
import java.sql.*;import java.util.*;import com.trombokendu.chronos.domain.*;
public final class Migrator {
 private final List<Migration> migrations=List.of(new Migration(){public int version(){return 1;}public void apply(Connection c)throws SQLException{try(Statement s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT UNIQUE NOT NULL,type TEXT NOT NULL,at INTEGER NOT NULL,payload TEXT NOT NULL,prev_hash TEXT NOT NULL,hash TEXT NOT NULL)");s.execute("CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL)");s.execute("CREATE TABLE IF NOT EXISTS anchors(seq INTEGER PRIMARY KEY,hash TEXT NOT NULL,exported_at INTEGER NOT NULL)");}}});
 public void migrate(Connection c){try(Statement s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY,applied_at INTEGER NOT NULL)");}catch(SQLException e){throw new PersistenceException("Cannot create schema_version",e);}for(Migration m:migrations){try(PreparedStatement q=c.prepareStatement("SELECT 1 FROM schema_version WHERE version=?")){q.setInt(1,m.version());try(ResultSet r=q.executeQuery()){if(r.next())continue;}}catch(SQLException e){throw new PersistenceException("Migration lookup failed",e);}try{c.setAutoCommit(false);m.apply(c);try(PreparedStatement i=c.prepareStatement("INSERT INTO schema_version VALUES(?,?)")){i.setInt(1,m.version());i.setLong(2,System.currentTimeMillis());i.executeUpdate();}c.commit();}catch(SQLException e){try{c.rollback();}catch(SQLException ignored){}throw new PersistenceException("Migration failed",e);}finally{try{c.setAutoCommit(true);}catch(SQLException ignored){}}}}
}
